const body = $input.first().json.body || {};
const message = typeof body.message === 'string' ? body.message.trim() : '';
const sessionId = typeof body.sessionId === 'string' ? body.sessionId : '';
const reject = (status, reply) => [{ json: { ok: false, status, reply } }];

if (!/^[A-Za-z0-9_-]{8,64}$/.test(sessionId)) return reject(400, 'Something went wrong. Please refresh the page and try again.');
if (!message) return reject(400, 'Please type a message.');
if (message.length > 500) return reject(400, 'Please keep messages under 500 characters.');

// Server-side limits (defense in depth; the main rate limit lives in the Next.js API route)
const DAILY_CAP = 400;   // total messages per day across all visitors
const SESSION_CAP = 40;  // messages per conversation per day
const data = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (data.day !== today) { data.day = today; data.total = 0; data.sessions = {}; }
data.total = (data.total || 0) + 1;
data.sessions = data.sessions || {};
data.sessions[sessionId] = (data.sessions[sessionId] || 0) + 1;

if (data.total > DAILY_CAP) return reject(429, 'Our assistant is taking a short break. Please use the contact form below or call (480) 555-0142.');
if (data.sessions[sessionId] > SESSION_CAP) return reject(429, "You've reached the message limit for this conversation. For anything else, please use the contact form or call (480) 555-0142.");

return [{ json: { ok: true, message, sessionId } }];

const req = $input.first().json;
const c = $getWorkflowStaticData('global');
const TTL = 10 * 60 * 1000; // re-read Notion at most every 10 minutes
const fresh = !!(c.kbCache && (Date.now() - c.kbCache.at) < TTL);
return [{ json: { message: req.message, sessionId: req.sessionId, cached: fresh, systemPrompt: fresh ? c.kbCache.systemPrompt : '' } }];

const richText = (arr) => (Array.isArray(arr) ? arr.map(r => r.plain_text ?? r.text?.content ?? '').join('') : '');
const blockText = (b) => {
  const d = b.type ? b[b.type] : null;
  if (d && Array.isArray(d.rich_text)) return richText(d.rich_text);
  if (typeof b.content === 'string') return b.content; // simplified Notion output
  return '';
};
const prefixes = { heading_1: '# ', heading_2: '## ', heading_3: '### ', bulleted_list_item: '- ', numbered_list_item: '- ', to_do: '- ' };

const kbBlocks = $('Get Knowledge Base').all().map(i => i.json);
const kb = kbBlocks
  .filter(b => b.type !== 'callout')
  .map(b => { const t = blockText(b); return t ? (prefixes[b.type] || '') + t : ''; })
  .filter(Boolean)
  .join('\n');

const promptBlocks = $('Get System Prompt').all().map(i => i.json);
const codeBlock = promptBlocks.find(b => b.type === 'code');
const prompt = codeBlock ? blockText(codeBlock) : '';

if (!kb || !prompt) {
  throw new Error('Knowledge Base or System Prompt is empty. Check the Notion pages, the code block on the System Prompt page, and that the n8n integration is connected to "Velure Med Spa — CRM".');
}

let systemPrompt = prompt.includes('{{KNOWLEDGE_BASE}}')
  ? prompt.replace('{{KNOWLEDGE_BASE}}', kb)
  : prompt + '\n\n<knowledge_base>\n' + kb + '\n</knowledge_base>';
// Curly braces can break the agent's prompt template; replace any that remain.
systemPrompt = systemPrompt.replace(/\{/g, '(').replace(/\}/g, ')');

const cache = $getWorkflowStaticData('global');
cache.kbCache = { at: Date.now(), systemPrompt };

const req = $('Check Cache').first().json;
return [{ json: { message: req.message, sessionId: req.sessionId, systemPrompt } }];

// Velure — shape the reply for the website: { reply, action? }.
// The Book button comes ONLY from a successful suggest_booking tool call,
// never from text the model wrote, so a reply cannot invent one.
const out = $input.first().json || {};
const steps = Array.isArray(out.intermediateSteps) ? out.intermediateSteps : [];

const parse = (v) => {
  if (v && typeof v === 'object') return v;
  if (typeof v !== 'string') return null;
  try { return JSON.parse(v); } catch { return null; }
};
// Sub-workflow tools may return an object, an array of items, or a JSON string of either.
const unwrap = (v) => {
  let x = parse(v);
  if (Array.isArray(x)) x = x[0];
  if (x && x.json && typeof x.json === 'object') x = x.json;
  if (x && typeof x.response === 'string') { const inner = parse(x.response); if (inner) x = inner; }
  return x && typeof x === 'object' ? x : null;
};

const TREATMENTS = new Set(['signature-glow-facial','wrinkle-relaxers','dermal-fillers',
  'collagen-microneedling','laser-rejuvenation','body-contouring','consultation']);
const clean = (a) => {
  if (!a || a.type !== 'book' || !TREATMENTS.has(a.treatmentId)) return null;
  const date = typeof a.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(a.date) ? a.date : null;
  const time = date && typeof a.time === 'string' && /^\d{2}:\d{2}$/.test(a.time) ? a.time : null;
  return { type: 'book', treatmentId: a.treatmentId, date, time };
};

let action = null;
const tools = [];
for (const step of steps) {
  const name = step && step.action && step.action.tool;
  if (!name) continue;
  tools.push(name);
  if (name !== 'suggest_booking') continue;
  const result = unwrap(step.observation);
  if (result && result.ok === true) action = clean(result.action) || action;
}

// Claude can return the final answer as content blocks ([{ type: 'text', text }]) instead of a string.
const textOf = (o) => {
  if (typeof o === 'string') return o;
  if (Array.isArray(o)) return o.map(textOf).filter(Boolean).join('\n');
  if (o && typeof o === 'object') {
    if (typeof o.text === 'string') return o.type && o.type !== 'text' ? '' : o.text;
    if ('output' in o) return textOf(o.output);
  }
  return '';
};
let reply = textOf(out.output).trim();
if (/^Agent stopped due to max iterations/i.test(reply)) reply = '';
// The widget renders plain text: strip stray markdown emphasis and headings.
reply = reply.replace(/\*\*(.+?)\*\*/g, '$1').replace(/^#{1,6}\s+/gm, '');
if (!reply) {
  reply = action
    ? 'You can finish your booking with the button below.'
    : 'Sorry, I could not put an answer together. Please try again, or use the contact form.';
}

return [{ json: { reply, action, tools: [...new Set(tools)] } }];
